void UDustAccumulationParticleComponent::UpdateParticleSettling(float DeltaTime)
{
	// Simulate particle settling under gravity
	for (FDustParticleData& Particle : ActiveParticles)
	{
		Particle.Age += DeltaTime;

		// Apply settling progression: particles gradually slow and settle
		float SettlingFactor = CalculateSettlingProgression(Particle.Age);
		Particle.Velocity.Z -= (ParticleGravityScale * 980.0f * DeltaTime); // Earth gravity in cm/s^2

		// As settling progresses, reduce horizontal velocity (dust falls straight)
		Particle.Velocity.X *= FMath::Pow(0.98f, DeltaTime); // Friction
		Particle.Velocity.Y *= FMath::Pow(0.98f, DeltaTime);

		// Update location
		Particle.Location += Particle.Velocity * DeltaTime;

		// Accumulate dust factor
		Particle.AccumulationFactor += SettlingFactor * DeltaTime * 0.5f;

		// Mark as settled if very slow
		if (Particle.Velocity.SizeSquared() < 1.0f && Particle.Age > 2.0f)
		{
			Particle.bSettled = true;
		}

		// Remove old particles
		if (Particle.Age > ParticleLifetime)
		{
			// Transfer settled dust to accumulation layer
			if (Particle.bSettled)
			{
				TotalAccumulation += Particle.AccumulationFactor;
			}
		}
	}

	// Remove expired particles
	ActiveParticles.RemoveAll([this](const FDustParticleData& Particle)
		{
			return Particle.Age > ParticleLifetime;
		});
}

void UDustAccumulationParticleComponent::UpdateAccumulationLayer()
{
	// Calculate current accumulation layer thickness
	CurrentAccumulationLayer = FMath::Min(TotalAccumulation, MaxAccumulationHeight) / MaxAccumulationHeight;
	PeakAccumulation = FMath::Max(PeakAccumulation, CurrentAccumulationLayer);
}

float UDustAccumulationParticleComponent::CalculateSettlingProgression(float Age) const
{
	// Sigmoid curve: slow at first, then accelerates, then plateaus
	// This models dust particles falling through air then settling
	float T = Age / ParticleLifetime;
	return FMath::Clamp(T * T, 0.0f, 1.0f); // Quadratic settling (can be tuned)
}

void UDustAccumulationParticleComponent::EmitDustAtLocation(FVector Location, int32 ParticleCount)
{
	if (UWorld* World = GetWorld())
	{
		LastEmissionTime = World->GetTimeSeconds();
	}

	for (int32 i = 0; i < ParticleCount; ++i)
	{
		FDustParticleData NewParticle;
		NewParticle.Location = Location;

		// Random horizontal velocity (cone around vertical)
		float RandomAngle = FMath::Rand() * PI * 2.0f;
		float RandomDist = FMath::Rand() * FootstepEmitRadius;
		NewParticle.Velocity.X = FMath::Cos(RandomAngle) * RandomDist * 0.5f;
		NewParticle.Velocity.Y = FMath::Sin(RandomAngle) * RandomDist * 0.5f;
		NewParticle.Velocity.Z = FMath::Rand() * 50.0f; // Upward velocity

		// Randomize vertex normal (mostly horizontal surfaces)
		NewParticle.VertexNormal = FVector(
			(FMath::Rand() - 0.5f) * 0.4f,
			(FMath::Rand() - 0.5f) * 0.4f,
			0.8f + (FMath::Rand() - 0.5f) * 0.2f
		).GetSafeNormal();

		NewParticle.Age = 0.0f;
		NewParticle.AccumulationFactor = 0.0f;
		NewParticle.bSettled = false;
		NewParticle.WindDriftAccumulator = FVector::ZeroVector;

		ActiveParticles.Add(NewParticle);
	}

	UE_LOG(LogTemp, Display, TEXT("[DustAccumulationParticleComponent] Emitted %d dust particles at (%.1f, %.1f, %.1f)"),
		ParticleCount, Location.X, Location.Y, Location.Z);

	// Also emit via Niagara if system is available
	if (DustParticleSystem && GetWorld())
	{
		UNiagaraFunctionLibrary::SpawnSystemAtLocation(GetWorld(), DustParticleSystem, Location);
	}
}

